// Builds one short alert for any failed outreach run (lead engine, dispatcher, sequencer, reply engine, portfolio inbound).
const j = $input.first().json || {};
const ex = j.execution || {};
const wf = j.workflow || {};
const trig = j.trigger || {};
const err = ex.error || trig.error || {};
const msg = String(err.message || err.description || 'Unknown error').replace(/\s+/g, ' ').slice(0, 400);
const node = ex.lastNodeExecuted || (err.node && err.node.name) || 'unknown node';
const sending = /dispatcher|sequencer/i.test(wf.name || '');
return [{ json: {
  alert_type: 'error',
  title: 'Outreach workflow failed: ' + String(wf.name || 'unknown workflow').slice(0, 80),
  message: 'Node: ' + node + '\nError: ' + msg +
    (sending ? '\nNo email is marked Sent unless the send succeeded; check the draft in Airtable.' : '') +
    (ex.url ? '\nExecution: ' + ex.url : (ex.id ? '\nExecution id: ' + ex.id : '')),
} }];
